 Game game(root/"campaign.save");game.themeChoice=ThemeChoice::Canyon;game.seedText="15";game.reviewShopBattery=true;game.nextBalancePreset=preset;game.launch(true);check(game.run&&game.error.empty(),"Game launch");Renderer renderer;game.updateCamera(10);
