 frame();check(game.run->batteryPickups.size()==1&&game.run->activeItem->charge==4&&game.balancePreset.defaultZoomPercent==165,"natural battery and labelled full active");capture("shop.png");auto at=game.run->batteryPickups[0].position;const int slot=game.run->batteryPickups[0].shopSlot;const auto spent=game.run->moneySpent;
