 game.close();renderer.unload();Game fresh(root/"campaign.save");check(fresh.nextBalancePreset&&fresh.nextBalancePreset->batteries==BatteryTuning{true,2,7}&&fresh.nextBalancePreset->defaultZoomPercent==165,"fresh process remembers battery controls and zoom");fresh.close();CloseWindow();std::cout<<"PASS actual Game/Renderer mouse UI, C use, real purchase, capacity gating, export/load/remember, Apply/revisit/retry and fresh process\n";
